<script lang="ts">
 import SourceSummary from './SourceSummary.svelte';
 import {onMount} from 'svelte';import {guardUnsaved} from '../unsaved';import {page} from '$app/state';import {Button} from '$lib/components/ui/button';import {Input} from '$lib/components/ui/input';import {Textarea} from '$lib/components/ui/textarea';import {request} from '../api';
 let source=$state(page.url.searchParams.get('asset')||''),videoId=$state(page.url.searchParams.get('video')||''),step=$state(0),title=$state(''),description=$state(''),visibility=$state('private'),audience=$state('free'),format=$state('standard'),ai=$state(false),rights=$state(false),busy=$state(false),loading=$state(true),error=$state(''),notice=$state(''),status=$state(''),origin=$state('generated'),eligibleShort=$state(false);
 let savedForm=$state(''),download=$state(''),asset=$state<any>(null);const snapshot=()=>JSON.stringify({title,description,visibility,audience,format,ai});
 guardUnsaved(()=>!loading&&!!savedForm&&snapshot()!==savedForm,'You have unsaved publication details.');
 const steps=['Details','Audience','Review'];
 onMount(()=>{void load();});async function load(){try{if(videoId){const v=await request(`/videos/${encodeURIComponent(videoId)}`);title=v.title;description=v.description;visibility=v.visibility;audience=v.audience;format=v.format;ai=v.ai_generated;source=v.source_asset_id;status=v.status;origin=v.origin;eligibleShort=v.height>v.width&&v.duration_ms>=3000&&v.duration_ms<=180000;}else if(source){const a=await request(`/media-assets/${encodeURIComponent(source)}`);origin=a.origin;eligibleShort=a.measured&&a.height>a.width&&a.duration_ms>=3000&&a.duration_ms<=180000;ai=a.origin==='generated';}else error='Choose a finished output or upload a video first.';if(source)asset=await request(`/media-assets/${encodeURIComponent(source)}`);}catch(e){error=(e as Error).message;}finally{loading=false;savedForm=snapshot();}}
 async function prepareDownload(){busy=true;error='';try{const result=await request(`/media-assets/${source}/download`);download=result.url;}catch(e){error=(e as Error).message;}finally{busy=false;}}
 async function save(publish=false){busy=true;error='';notice='';try{const body={title:title.trim(),description,visibility,audience,format,ai_generated:origin==='generated'||ai};if(videoId){await request(`/videos/${videoId}`,body,'PATCH');}else{const v=await request('/publications',{...body,source_asset_id:source,rights_confirmed:rights});videoId=v.id;}if(publish)await request(`/videos/${videoId}/publish`,{},'POST',{'Idempotency-Key':`publication-${videoId}`});const v=await request(`/videos/${videoId}`);status=v.status;savedForm=snapshot();notice=publish?(status==='published'?'Your publication is ready.':'Your video is being prepared for viewing. You can leave this page.'):'Draft saved.';}catch(e){error=(e as Error).message;}finally{busy=false;}}
</script>
<div class="page-heading"><h1>{videoId?'Your publication':'Publish on VideoFlow'}</h1><p>Choose how your video appears and who can watch.</p></div>
{#if source&&!loading}<div class="source-actions"><Button variant="ghost" size="sm" disabled={busy} onclick={prepareDownload}>Prepare original download</Button>{#if download}<a href={download}>Download original video</a>{/if}</div>{/if}
<nav aria-label="Publication steps" class="composer-steps">{#each steps as label,index}<button disabled={busy||loading||(!title.trim()&&index>0)} aria-current={step===index?'step':undefined} onclick={()=>step=index}>{label}</button>{/each}</nav>
{#if error}<div class="cloud-alert" role="alert">{error}</div>{/if}{#if notice}<p class="cloud-notice" role="status">{notice}</p>{/if}
{#if loading}<p role="status">Loading publication…</p>{:else if source}<form class="composer" onsubmit={e=>{e.preventDefault();if(step<2)step++;else void save(true);}}>
{#if step===0}{#if asset}<SourceSummary {asset} previewEnabled={true} label="Selected video"/>{/if}<label for="publish-title">Title</label><Input id="publish-title" bind:value={title} maxlength={180} required/><label for="publish-description">Description</label><Textarea id="publish-description" bind:value={description} rows={5} maxlength={5000}/>{#if origin==='generated'}<p class="field-help">This video will be labelled AI-generated.</p>{:else}<label class="composer-check"><input type="checkbox" bind:checked={ai}/>This video contains AI-generated content</label>{/if}<label class="composer-check"><input type="checkbox" bind:checked={rights} required={!videoId}/>I have the rights to publish this video and its audio.</label>
{:else if step===1}<label for="publish-format">Viewing format</label><select id="publish-format" bind:value={format}><option value="standard">Standard video</option>{#if eligibleShort}<option value="short">Short</option>{/if}</select>{#if !eligibleShort}<p class="field-help">Shorts require a validated portrait video between 3 seconds and 3 minutes.</p>{/if}<label for="publish-visibility">Visibility</label><select id="publish-visibility" bind:value={visibility}><option value="private">Private — only you</option><option value="unlisted">Unlisted — anyone with the link who has access</option><option value="public">Public — discoverable on VideoFlow</option></select><label for="publish-audience">Viewing access</label><select id="publish-audience" bind:value={audience}><option value="free">Free</option><option value="members">Premium members</option></select><p class="field-help">Premium is one subscription across VideoFlow. It is separate from following your profile.</p>
{:else}<div class="publication-review">{#if asset}<SourceSummary {asset} label="Source version"/>{/if}<h2>{title}</h2><p>{description||'No description added.'}</p><dl><div><dt>Visibility</dt><dd>{visibility}</dd></div><div><dt>Access</dt><dd>{audience==='members'?'VideoFlow Premium':'Free'}</dd></div><div><dt>Format</dt><dd>{format==='short'?'Short':'Standard video'}</dd></div></dl><p class="field-help">Your video becomes watchable after processing completes. Editing your Studio project won't change this published version.</p></div>{/if}
<div class="composer-actions">{#if step>0}<Button type="button" variant="ghost" disabled={busy} onclick={()=>step--}>Back</Button>{/if}<Button type="button" variant="outline" disabled={busy||!title.trim()||(!videoId&&!rights)} onclick={()=>save()}>Save draft</Button><Button type="submit" disabled={busy||!title.trim()||(!videoId&&!rights)}>{busy?'Saving…':step<2?'Continue':'Publish video'}</Button></div>{#if status==='published'}<Button href={`/watch/${videoId}`} variant="outline">View video</Button><p class="field-help">Publishing does not guarantee rewards. <a href="/earnings?tab=videos">Review video reward eligibility</a> or <a href="/earnings?tab=program">read the program rules</a>.</p>{:else if status==='processing'}<p class="field-help" role="status">Processing. Check My content for updates.</p>{/if}</form>{:else}<Button href="/studio/videos">Choose a finished video</Button><Button variant="outline" href="/studio/upload">Upload a video</Button>{/if}
<style>.source-actions{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin-bottom:16px}.source-actions a{font-size:13px;text-decoration:underline;text-underline-offset:4px}.composer{max-width:720px;display:grid;gap:12px}.composer>label{font-size:13px;margin-top:12px}.composer-steps{display:flex;gap:25px;border-bottom:1px solid var(--border);margin-bottom:28px}.composer-steps button{padding:12px 0;font-size:13px;color:var(--muted-foreground);border-bottom:2px solid transparent}.composer-steps button[aria-current=step]{color:var(--foreground);border-color:var(--primary)}.composer select{padding:12px;background:var(--background);border:1px solid var(--border);border-radius:8px;font-size:13px}.composer-check{display:flex;gap:10px;align-items:center;line-height:1.6}.composer-check input{width:18px;height:18px;flex-shrink:0;accent-color:var(--primary)}.composer-actions{display:flex;gap:12px;justify-content:flex-end;margin:24px 0}.publication-review h2{font-size:20px;font-weight:600;margin-bottom:12px}.publication-review p{font-size:13px;line-height:1.8;white-space:pre-wrap}.publication-review dl{margin:25px 0}.publication-review dl>div{display:flex;justify-content:space-between;gap:20px;padding:12px 0;border-bottom:1px solid var(--border);font-size:13px}.publication-review dt{color:var(--muted-foreground)}.publication-review dd{text-transform:capitalize}@media(max-width:500px){.composer-actions{flex-wrap:wrap}.composer-actions :global(button){flex:1;min-height:44px}}</style>
